using System.Net;using Npgsql;using Xunit;
namespace BARANG.Core.IntegrationTests.Database;
#pragma warning disable CA1707,xUnit1051
[Collection(PostgreSqlDatabaseFixture.CollectionName)]public sealed class WorkflowFoundationTests(PostgreSqlDatabaseFixture database)
{
 [Fact]public async Task Migration_creates_workflow_tables_permissions_rls_and_immutable_history(){await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync();await using NpgsqlCommand q=c.CreateCommand();q.CommandText="SELECT (SELECT count(*) FROM information_schema.tables WHERE table_schema='barang' AND table_name IN ('workflow_instances','human_tasks','workflow_sla_policies','workflow_escalations','workflow_history','workflow_reconciliation_issues')),(SELECT count(*) FROM barang.permissions WHERE code IN ('workflow.read','workflow.task.claim','workflow.task.complete','workflow.manage')),(SELECT count(*) FROM pg_policies WHERE schemaname='barang' AND tablename IN ('workflow_instances','human_tasks','workflow_sla_policies','workflow_escalations','workflow_history','workflow_reconciliation_issues')),has_table_privilege(current_user,'barang.workflow_history','UPDATE'),has_table_privilege(current_user,'barang.workflow_history','DELETE')";await using NpgsqlDataReader r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());Assert.Equal(6,r.GetInt64(0));Assert.Equal(4,r.GetInt64(1));Assert.Equal(6,r.GetInt64(2));Assert.False(r.GetBoolean(3));Assert.False(r.GetBoolean(4));}
 [Fact]public async Task Workflow_endpoints_require_authentication(){using PostgreSqlCoreApiFactory f=new(database.ConnectionString);using HttpClient c=f.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync($"/api/v1/workflows/{Guid.NewGuid()}")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/v1/workflows/tasks/mine")).StatusCode);}
 [Fact]public async Task Workflow_rls_hides_rows_without_company_context(){await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync();await using NpgsqlCommand clear=c.CreateCommand();clear.CommandText="RESET barang.company_id";await clear.ExecuteNonQueryAsync();await using NpgsqlCommand q=c.CreateCommand();q.CommandText="SELECT count(*) FROM barang.workflow_instances";Assert.Equal(0L,(long)(await q.ExecuteScalarAsync())!);}
}
#pragma warning restore CA1707,xUnit1051
